import { useState } from 'react';
import {
  JxCard,
  JxStepper,
  JxStep,
  JxInput,
  JxButton,
  JxStack,
  JxText,
  JxDivider,
} from '@jinx-ui/react';

type ContactData = {
  fullName: string;
  email: string;
  phone: string;
};

type AddressData = {
  country: string;
  city: string;
  street: string;
  zip: string;
};

export type RegistrationFormData = {
  contact: ContactData;
  address: AddressData;
};

export interface RegistrationWizardProps {
  onSubmit: (data: RegistrationFormData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [contact, setContact] = useState<ContactData>({
    fullName: '',
    email: '',
    phone: '',
  });
  const [address, setAddress] = useState<AddressData>({
    country: '',
    city: '',
    street: '',
    zip: '',
  });

  const isFirstStep = stepIndex === 0;
  const isLastStep = stepIndex === STEPS.length - 1;

  const goNext = () => {
    if (!isLastStep) {
      setStepIndex((prev) => prev + 1);
    }
  };

  const goBack = () => {
    if (!isFirstStep) {
      setStepIndex((prev) => prev - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit({ contact, address });
  };

  return (
    <JxCard style={{ padding: 'var(--jx-space-6)', maxWidth: 480 }}>
      <JxStepper activeStep={stepIndex} style={{ marginBottom: 'var(--jx-space-6)' }}>
        {STEPS.map((label) => (
          <JxStep key={label} label={label} />
        ))}
      </JxStepper>

      {stepIndex === 0 && (
        <JxStack direction="column" gap="var(--jx-space-4)">
          <JxInput
            label="Полное имя"
            value={contact.fullName}
            onChange={(e) =>
              setContact((prev) => ({ ...prev, fullName: e.target.value }))
            }
          />
          <JxInput
            label="Email"
            type="email"
            value={contact.email}
            onChange={(e) =>
              setContact((prev) => ({ ...prev, email: e.target.value }))
            }
          />
          <JxInput
            label="Телефон"
            type="tel"
            value={contact.phone}
            onChange={(e) =>
              setContact((prev) => ({ ...prev, phone: e.target.value }))
            }
          />
        </JxStack>
      )}

      {stepIndex === 1 && (
        <JxStack direction="column" gap="var(--jx-space-4)">
          <JxInput
            label="Страна"
            value={address.country}
            onChange={(e) =>
              setAddress((prev) => ({ ...prev, country: e.target.value }))
            }
          />
          <JxInput
            label="Город"
            value={address.city}
            onChange={(e) =>
              setAddress((prev) => ({ ...prev, city: e.target.value }))
            }
          />
          <JxInput
            label="Улица и дом"
            value={address.street}
            onChange={(e) =>
              setAddress((prev) => ({ ...prev, street: e.target.value }))
            }
          />
          <JxInput
            label="Индекс"
            value={address.zip}
            onChange={(e) =>
              setAddress((prev) => ({ ...prev, zip: e.target.value }))
            }
          />
        </JxStack>
      )}

      {stepIndex === 2 && (
        <JxStack direction="column" gap="var(--jx-space-3)">
          <JxText variant="subtitle">Контакты</JxText>
          <JxText>Имя: {contact.fullName || '—'}</JxText>
          <JxText>Email: {contact.email || '—'}</JxText>
          <JxText>Телефон: {contact.phone || '—'}</JxText>

          <JxDivider />

          <JxText variant="subtitle">Адрес</JxText>
          <JxText>Страна: {address.country || '—'}</JxText>
          <JxText>Город: {address.city || '—'}</JxText>
          <JxText>Улица: {address.street || '—'}</JxText>
          <JxText>Индекс: {address.zip || '—'}</JxText>
        </JxStack>
      )}

      <JxStack
        direction="row"
        justify="space-between"
        style={{ marginTop: 'var(--jx-space-6)' }}
      >
        <JxButton variant="secondary" onClick={goBack} disabled={isFirstStep}>
          Назад
        </JxButton>

        {isLastStep ? (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={goNext}>
            Дальше
          </JxButton>
        )}
      </JxStack>
    </JxCard>
  );
}

